const cfg = { saida: { max_mensagens: {{BV:saida.max_mensagens}}, max_chars_mensagem: {{BV:saida.max_chars_mensagem}} },
  lista: { max_itens: {{BV:lista.max_itens}}, max_titulo: {{BV:lista.max_titulo}} },
  graces: { barbeiro_teste_id: '{{BV:graces.barbeiro_teste_id}}', teste_liberado: {{BV:graces.teste_contatos}}.includes(String(($('Gatilho').first().json || {}).telefone || '').replace(/\D/g, '')) },
  digitando: { ms_por_char: {{BV:digitando.ms_por_char}}, min_ms: {{BV:digitando.min_ms}}, max_ms: {{BV:digitando.max_ms}} } };
const out = String(($('Agente').first().json || {}).output || '');
const oferta = $input.first().json.opcoes || null;
const antes = (($('Ler contexto').first().json) || {}).opcoes || null;
let saida = bvCompor(out, oferta, cfg, JSON.stringify(oferta) !== JSON.stringify(antes));
if (!saida.length) saida = [{ n: 1, tipo: 'texto', texto: "{{BV:textos.reformular}}" }];
saida = bvSaudar(saida, $('Preparar').first().json.primeira_da_sessao);
return [{ json: { saida } }];

