const cfg = { saida: { max_mensagens: {{BV:saida.max_mensagens}}, max_chars_mensagem: {{BV:saida.max_chars_mensagem}} },
  lista: { max_itens: {{BV:lista.max_itens}}, max_titulo: {{BV:lista.max_titulo}} },
  graces: { barbeiro_teste_id: '{{BV:graces.barbeiro_teste_id}}', teste_liberado: {{BV:graces.teste_contatos}}.includes(String(($('Gatilho').first().json || {}).telefone || '').replace(/\D/g, '')) },
  digitando: { ms_por_char: {{BV:digitando.ms_por_char}}, min_ms: {{BV:digitando.min_ms}}, max_ms: {{BV:digitando.max_ms}} } };
const g = $('Gatilho').first().json;
const j = $input.first().json;
const dig = (s) => String(s || '').replace(/\D/g, '');
// so contatos de escrita (teste.contatos_escrita, P2) recebem de verdade; o resto e simulado
const escrita = {{BV:teste.contatos_escrita}}.map(dig);
const simulado = '{{BV:ambiente}}' === 'integracao' && !escrita.includes(dig(g.telefone)); // trava so no TESTE
const wid = '{{BV:chatmaster.whatsapp_id}}';
const reqs = (j.saida || []).slice(0, 4).map((m) => {
  // contato no formato LID ("<id>@lid") vai pelo endpoint de LID, com o valor intacto
  const lid = /@lid$/.test(String(g.telefone));
  const number = lid ? String(g.telefone) : dig(g.telefone);
  const digitando = { number, body: 'composing', caption: '', whatsappId: wid };
  const envio = m.tipo === 'lista'
    ? { path: '/api/messages/whatsmeow/sendListPRO', body: { number, openTicket: '1', queueId: '0', whatsappId: wid, body: { Desc: m.texto, ButtonText: "{{BV:textos.lista_botao}}", TopText: "{{BV:textos.lista_topo}}", List: (m.opcoes || []).map((o) => ({ RowId: o.id, title: o.rotulo, desc: '' })) } } }
    : { path: lid ? '/api/messages/whatsmeow/sendTextPROLid' : '/api/messages/send', body: { number, openTicket: '0', queueId: '0', whatsappId: wid, body: m.texto } };
  return { n: m.n, tipo: m.tipo, texto: m.texto, digitando, envio, espera_s: Math.ceil(bvDigitacaoMs(m.texto, cfg) / 1000) };
});
return [{ json: { simulado, reqs, total: reqs.length } }];
